<?php
namespace Cyberfort\AIRegister; defined( 'ABSPATH' ) || exit;
class Settings { public function init(): void { add_action( 'admin_menu', [ $this, 'menu' ] ); add_action( 'admin_init', [ $this, 'settings' ] ); add_action( 'wp_ajax_cfair_test_connection', [ $this, 'test' ] ); add_action( 'admin_post_cfair_clear_cache', [ $this, 'clear' ] ); } public function menu(): void { add_options_page( __( 'AI Register', 'cyberfort-ai-register' ), __( 'AI Register', 'cyberfort-ai-register' ), 'manage_options', 'cyberfort-ai-register', [ $this, 'page' ] ); } public function settings(): void { foreach ( [ 'cfair_server_url' => [ $this, 'url' ], 'cfair_api_key' => [ $this, 'key' ], 'cfair_environment' => null, 'cfair_language' => null, 'cfair_cache_duration' => 'absint', 'cfair_stale_retention' => 'absint', 'cfair_base_slug' => 'sanitize_title', 'cfair_delete_data' => 'absint' ] as $option => $callback ) register_setting( 'cfair_settings', $option, [ 'sanitize_callback' => $callback ] ); } public function url( $url ): string { $url = untrailingslashit( esc_url_raw( trim( $url ) ) ); $parts = wp_parse_url( $url ); $development = 'development' === get_option( 'cfair_environment' ); if ( ! $parts || ! empty( $parts['query'] ) || ! empty( $parts['fragment'] ) || ( 'https' !== ( $parts['scheme'] ?? '' ) && ! ( $development && in_array( $parts['host'] ?? '', [ 'localhost', '127.0.0.1' ], true ) ) ) ) { add_settings_error( 'cfair_settings', 'cfair_url', __( 'Enter a valid HTTPS server URL without a query or fragment.', 'cyberfort-ai-register' ) ); return (string) get_option( 'cfair_server_url' ); } return $url; } public function key( $key ): string { $key = trim( (string) $key ); return '' === $key ? (string) get_option( 'cfair_api_key' ) : sanitize_text_field( $key ); } public function page(): void { if ( ! current_user_can( 'manage_options' ) ) return; require CFAIR_PATH . 'templates/admin/settings-page.php'; } public function test(): void { check_ajax_referer( 'cfair_test_connection' ); if ( ! current_user_can( 'manage_options' ) ) wp_send_json_error( [ 'message' => __( 'Unauthorized.', 'cyberfort-ai-register' ) ], 403 ); $result = ( new Api_Client() )->test_connection(); isset( $result['error'] ) ? wp_send_json_error( [ 'message' => $result['error'] ] ) : wp_send_json_success( $result ); } public function clear(): void { check_admin_referer( 'cfair_clear_cache' ); if ( current_user_can( 'manage_options' ) ) ( new Cache() )->clear(); wp_safe_redirect( admin_url( 'options-general.php?page=cyberfort-ai-register&cleared=1' ) ); exit; } }
